@startuml

class Product {
  + Name : string
  + Description : string
  + NetPrice : double
}

class Manufacturer {
  + Name : string
}

class Country {
  + Name : string
  + VATRate : float
  + Currency : string
  + ConversionRateToEuro : float
}

class Representative {
  + FirstName : string
  + LastName : string
  + SocialSecurityNumber : string
  + TelephoneNumber : string
  + EmailAddress : string
}

class Customer {
  + Name : string
  + Address : string
  + TelephoneNumber : string
  + EmailAddress : string
}

class Order {
  + OrderID : string
  + Quantity : int
  + OrderDate : date
  + DesiredDeliveryDate : date
}

Manufacturer "1" -- "*" Product : manufactures
Product "*" -- "1" Country : manufactured_in
Product "*" -- "*" Country : available_in
Representative "1" -- "1" Country : responsible_for
Representative "1" -- "*" Order : places
Customer "*" -- "*" Country : resells_in
Customer "1" -- "*" Order : places_via_representative
Order "*" -- "1" Product : refers_to
Order "*" -- "1" Representative : placed_by

@enduml

